code='''from collections import Counter

def transform(grid):
    """Complete the rectangular frame marked by the foreground cells."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    out = [row[:] for row in grid]

    def fill(r, c):
        if grid[r][c] == background:
            out[r][c] = 2

    # Complete the outside rectangle around the marked pattern.
    for c in range(cmin, cmax + 1):
        fill(rmin, c)
        fill(rmax, c)
    for r in range(rmin, rmax + 1):
        fill(r, cmin)
        fill(r, cmax)

    # Complete any interior divider that is marked at both opposite edges.
    for c in range(cmin + 1, cmax):
        if grid[rmin][c] != background and grid[rmax][c] != background:
            for r in range(rmin + 1, rmax):
                fill(r, c)
    for r in range(rmin + 1, rmax):
        if grid[r][cmin] != background and grid[r][cmax] != background:
            for c in range(cmin + 1, cmax):
                fill(r, c)
    return out
